40	.no-works-canvas {
41	  position: relative;
42	  z-index: var(--z-index-works-canvas);
43	  pointer-events: auto;
44	
45	  &[data-view="scatter"] {
46	    position: fixed;
47	    inset: 0;
48	    pointer-events: none;
49	  }
50	
51	  &[data-view="grid"] {
52	    min-height: 100vh;
53	    min-height: 100dvh;
54	    padding-top: var(--header-height);
55	  }
56	
57	  &__canvas {
58	    position: fixed;
59	    inset: 0;
60	    z-index: 0;
61	    width: 100%;
62	    height: 100%;
63	    display: block;
64	    pointer-events: auto;
65	    transition: opacity var(--transition-default);
66	
67	    &.is-hidden {
68	      pointer-events: none;
69	      visibility: hidden;
70	      opacity: 0;
71	    }
72	  }
73	
74	  &__background {
75	    position: fixed;
76	    inset: 0;
77	    z-index: -1;
78	    width: 100%;
79	    height: 100%;
80	    display: block;
81	    pointer-events: none;
82	  }
83	
84	  &__bottom-toggle {
85	    z-index: var(--z-index-works-hud);
86	    display: flex;
87	    align-items: center;
88	    position: relative;
89	    min-width: fluid(164, 192);
90	    padding: 4px;
91	    pointer-events: auto;
92	    overflow: hidden;
93	    border: 1px solid color-mix(in srgb, var(--clr-white-100) 18%, transparent);
94	    border-radius: 999px;
95	    background: color-mix(in srgb, var(--clr-black-100) 60%, transparent);
96	    backdrop-filter: blur(12px) saturate(140%);
97	    -webkit-backdrop-filter: blur(12px) saturate(140%);
98	    transition:
99	      opacity var(--transition-default),
100	      transform var(--transition-default);
101	
102	    &[hidden],
103	    &[data-ready="false"] {
104	      opacity: 0;
105	      pointer-events: none;
106	      transform: translateX(-50%) translateY(20px);
107	    }
108	
109	    &[data-ready="true"] {
110	      opacity: 1;
111	      transform: translateX(-50%) translateY(0);
112	    }
113	
114	    .no-works-canvas__toggle-rect {
115	      position: absolute;
116	      inset: 4px auto 4px 4px;
117	      width: calc(50% - 4px);
118	      border-radius: 999px;
119	      background: color-mix(in srgb, var(--clr-white-100) 12%, transparent);
120	      transition:
121	        transform var(--transition-default),
122	        background-color var(--transition-default);
123	      pointer-events: none;
124	      z-index: 0;
125	    }
126	
127	    &[data-view="scatter"] .no-works-canvas__toggle-rect {
128	      transform: translateX(100%);
129	    }
130	
131	    a,
132	    button {
133	      @include font("f-body-4");
134	      position: relative;
135	      z-index: 1;
136	      flex: 1 1 0;
137	      min-width: 0;
138	      font-family: var(--family-ui);
139	      letter-spacing: 0.04em;
140	      color: color-mix(in srgb, var(--clr-white-100) 56%, transparent);
141	      background: transparent;
142	      border: none;
143	      padding: 0.75rem 1rem;
144	      cursor: pointer;
145	      text-align: center;
146	      text-decoration: none;
147	      transition: color var(--transition-fast);
148	
149	      &[aria-selected="true"],
150	      &.is-active {
151	        color: var(--clr-white-100);
152	      }
153	
154	      &:hover {
155	        color: color-mix(in srgb, var(--clr-white-100) 84%, transparent);
156	      }
157	    }
158	  }
159	
160	  &__bottom-controls {
161	    position: fixed;
162	    bottom: var(--gutter-xl);
163	    left: 50%;
164	    z-index: var(--z-index-works-hud);
165	    display: flex;
166	    align-items: center;
167	    gap: 0.75rem;
168	    transform: translateX(-50%);
169	    transition:
170	      opacity var(--transition-default),
171	      transform var(--transition-default);
172	
173	    &[hidden],
174	    &[data-ready="false"] {
175	      opacity: 0;
176	      pointer-events: none;
177	      transform: translateX(-50%) translateY(20px);
178	    }
179	
180	    &[data-ready="true"] {
181	      opacity: 1;
182	      transform: translateX(-50%) translateY(0);
183	    }
184	  }
185	
186	  &__filter-wrap {
187	    position: relative;
188	    display: flex;
189	    align-items: center;
190	    pointer-events: auto;
191	
192	    &[hidden],
193	    &.is-hidden,
194	    .no-works-canvas[data-view="grid"] & {
195	      display: none;
196	      pointer-events: none;
197	    }
198	  }
199	
200	  &__filter-button {
201	    @include font("f-body-4");
202	    min-width: fluid(112, 144);
203	    display: inline-flex;
204	    align-items: center;
205	    justify-content: space-between;
206	    gap: 0.875rem;
207	    padding: 0.75rem 1rem;
208	    border: 1px solid color-mix(in srgb, var(--clr-white-100) 18%, transparent);
209	    border-radius: 999px;
210	    background: color-mix(in srgb, var(--clr-black-100) 82%, transparent);
211	    color: var(--clr-white-100);
212	    font-family: var(--family-ui);
213	    letter-spacing: 0.04em;
214	    cursor: pointer;
215	    transition:
216	      color var(--transition-fast),
217	      border-color var(--transition-fast),
218	      background-color var(--transition-fast);
219	
220	    &::after {
221	      content: "";
222	      width: 0.5rem;
223	      height: 0.5rem;
224	      border-right: 1px solid currentColor;
225	      border-bottom: 1px solid currentColor;
226	      transform: translateY(-0.1rem) rotate(45deg);
227	      transition: transform var(--transition-fast);
228	      flex-shrink: 0;
229	    }
230	
231	    &:hover,
232	    &[aria-expanded="true"] {
233	      background: color-mix(in srgb, var(--clr-black-100) 74%, transparent);
234	      border-color: color-mix(in srgb, var(--clr-white-100) 28%, transparent);
235	    }
236	
237	    &[aria-expanded="true"]::after {
238	      transform: translateY(0.1rem) rotate(225deg);
239	    }
240	  }
241	
242	  &__filter-button-label {
243	    display: inline-block;
244	    max-width: fluid(96, 120);
245	    overflow: hidden;
246	    text-overflow: ellipsis;
247	    white-space: nowrap;
248	    vertical-align: bottom;
249	    transition: opacity 0.3s ease, transform 0.3s ease;
250	  }
251	
252	  &__filter-button.is-filter-label-leaving &__filter-button-label {
253	    opacity: 0;
254	    transform: translateY(4px);
255	  }
256	
257	  &__filter-button.is-filter-label-entering &__filter-button-label {
258	    animation: works-filter-label-in 0.3s ease both;
259	  }
260	
261	  &__filter-panel {
262	    position: absolute;
263	    left: 0;
264	    bottom: calc(100% + 0.5rem);
265	    display: grid;
266	    gap: 0.25rem;
267	    min-width: 180px;
268	    padding: 0.375rem;
269	    border: 1px solid color-mix(in srgb, var(--clr-white-100) 16%, transparent);
270	    border-radius: 1rem;
271	    background: color-mix(in srgb, var(--clr-black-100) 88%, transparent);
272	    box-shadow: 0 12px 28px rgba(0, 0, 0, 0.22);
273	    opacity: 0;
274	    transform: translate3d(0, 10px, 0);
275	    pointer-events: none;
276	    transition: opacity 0.3s ease, transform 0.3s ease;
277	
278	    &.is-open {
279	      opacity: 1;
280	      transform: translate3d(0, 0, 0);
281	      pointer-events: auto;
282	    }
283	  }
284	
285	  &__filter-option {
286	    @include font("f-body-4");
287	    width: 100%;
288	    padding: 0.625rem 0.875rem;
289	    border: none;
290	    border-radius: 0.75rem;
291	    background: transparent;
292	    color: color-mix(in srgb, var(--clr-white-100) 72%, transparent);
293	    font-family: var(--family-ui);
294	    letter-spacing: 0.02em;
295	    text-align: left;
296	    cursor: pointer;
297	    transition:
298	      color var(--transition-fast),
299	      background-color var(--transition-fast);
300	
301	    &:hover,
302	    &.is-active {
303	      color: #fff;
304	      background: color-mix(in srgb, var(--clr-white-100) 10%, transparent);
305	    }
306	  }
307	
308	  @include mq(md) {
309	    &__bottom-controls {
310	      width: calc(100vw - fluid(24, 32));
311	      max-width: fluid(340, 420);
312	      gap: fluid(6, 10);
313	    }
314	
315	    &__bottom-toggle,
316	    &__filter-wrap {
317	      flex: 1 1 0;
318	    }
319	
320	    &__bottom-toggle,
321	    &__filter-button {
322	      min-width: 0;
323	    }
324	
325	    &__filter-button {
326	      width: 100%;
327	    }
328	
329	    &__filter-panel {
330	      width: 100%;
331	      max-height: min(50vh, fluid(280, 360));
332	      overflow-y: auto;
333	    }
334	  }
335	
336	  @include mq(sm) {
337	    &__bottom-controls {
338	      gap: fluid(4, 6);
339	    }
340	
341	    &__bottom-toggle {
342	      @include font("f-body-5");
343	    }
344	  }
345	
346	  &__grid {
347	    position: relative;
348	    z-index: var(--z-index-works-canvas);
349	    overflow: visible;
350	    pointer-events: auto;
351	    min-height: calc(100vh - var(--header-height));
352	    min-height: calc(100dvh - var(--header-height));
353	    padding: var(--gutter-2xl) 0;
354	    background: transparent;
355	    transition: opacity var(--transition-default);
356	
357	    .no-works-canvas[data-view="scatter"] & {
358	      position: fixed;
359	      inset: 0;
360	      overflow: auto;
361	      margin-top: var(--header-height);
362	      min-height: 0;
363	    }
364	
365	    &.is-hidden {
366	      display: none !important;
367	    }
368	
369	    &:not(.is-hidden) {
370	      display: block;
371	    }
372	
373	    &.is-transitioning-in {
374	      opacity: 1;
375	    }
376	
377	    .no-sub-works {
378	      margin-top: 0;
379	      padding-top: 0;
380	    }
381	
382	    .no-works-canvas__grid-badge,
383	    .no-works-canvas__grid-link {
384	      @include font("f-body-4");
385	      font-family: var(--family-ui);
386	      color: var(--clr-white-88);
387	    }
388	    .no-works-canvas__grid-badge {
389	      width: 100%;
390	    }
391	    /* View Modal: 코너 버튼(.no-corner-btn) 스타일, 색상만 그리드 톤으로 */
392	    .no-works-canvas__grid-link.no-corner-btn {
393	      --corner-btn-color: var(--clr-white-88);
394	      --corner-btn-hover-color: var(--clr-white-100);
395	      @include font("f-body-3");
396	      color: var(--corner-btn-color);
397	
398	      &:hover {
399	        color: var(--corner-btn-hover-color);
400	      }
401	
402	      @include mq(sm) {
403	        display: flex;
404	        width: 100%;
405	      }
406	    }
407	
408	    /* Grid 진입 애니: 필터 왼쪽에서 등장, 갤러리 아이템 아래→위 stagger */
409	    .no-sub-works__gallery-item {
410	      transform: translateY(48px);
411	      opacity: 0;
412	      transition:
413	        transform var(--transition-default),
414	        opacity var(--transition-default);
415	    }
416	
417	    &.is-grid-enter .no-sub-works__gallery-item {
418	      transform: translateY(0);
419	      opacity: 1;
420	
421	      @for $i from 1 through 32 {
422	        &:nth-child(#{$i}) {
423	          transition-delay: #{120ms + ($i - 1) * 80}ms;
424	        }
425	      }
426	
427	      &:nth-child(n + 33) {
428	        transition-delay: #{120ms + 31 * 80}ms;
429	      }
430	    }
431	  }
432	
433	  &__drag-hint {
434	    position: fixed;
435	    inset: 0;
436	    z-index: calc(var(--z-index-works-hud) - 1);
437	    display: grid;
438	    place-items: center;
439	    pointer-events: none;
440	    opacity: 0;
441	    visibility: hidden;
442	    transition: opacity var(--transition-default);
443	
444	    &:not(.is-visible):not(.is-hiding) {
445	      opacity: 0;
446	      visibility: hidden;
447	
448	      .no-works-canvas__drag-hint-card {
449	        transform: translate3d(0, 28px, 0);
450	      }
451	    }
452	
453	    &.is-visible {
454	      opacity: 1;
455	      visibility: visible;
456	
457	      .no-works-canvas__drag-hint-card {
458	        transform: translate3d(0, 0, 0);
459	      }
460	    }
461	
462	    &.is-hiding {
463	      opacity: 0;
464	      visibility: visible;
465	
466	      .no-works-canvas__drag-hint-card {
467	        transform: translate3d(0, 28px, 0);
468	      }
469	    }
470	  }
471	
472	  &__drag-hint-card {
473	    --corner-bracket-size: var(--corner-bracket-size-lg);
474	    --corner-stroke-width: 3;
475	    --corner-glow-blur: 6px;
476	    --corner-glow-spread: 12px;
477	    position: relative;
478	    isolation: isolate;
479	    overflow: hidden;
480	    display: grid;
481	    justify-items: center;
482	    gap: var(--gutter-xs);
483	    padding: calc(var(--gutter-lg) + 6px) calc(var(--gutter-xl) + 4px);
484	    min-width: min(320px, calc(100vw - 40px));
485	    background: #000;
486	    transform: translate3d(0, 28px, 0);
487	    transition:
488	      transform 420ms cubic-bezier(0.22, 1, 0.36, 1),
489	      opacity var(--transition-default);
490	    will-change: transform, opacity;
491	    backface-visibility: hidden;
492	    contain: paint;
493	    box-shadow:
494	      0 22px 72px rgba(0, 0, 0, 0.26),
495	      0 14px 30px rgba(0, 0, 0, 0.22);
496	
497	    &::before,
498	    &::after {
499	      content: "";
500	      position: absolute;
501	      inset: 0;
502	      pointer-events: none;
503	      z-index: 0;
504	    }
505	
506	    &::before {
507	      inset: 0;
508	      padding: 1px;
509	      background: #fff;
510	      -webkit-mask:
511	        linear-gradient(#000 0 0) content-box,
512	        linear-gradient(#000 0 0);
513	      -webkit-mask-composite: xor;
514	      mask:
515	        linear-gradient(#000 0 0) content-box,
516	        linear-gradient(#000 0 0);
517	      mask-composite: exclude;
518	      opacity: 0.92;
519	    }
520	
521	    &::after {
522	      inset: 1px;
523	      background: transparent;
524	      opacity: 0;
525	    }
526	  }
527	
528	  &__drag-hint-corner {
529	    color: #fff;
530	    z-index: 2;
531	  }
532	
533	  &__drag-hint-icon,
534	  &__drag-hint-text {
535	    position: relative;
536	    z-index: 1;
537	  }
538	
539	  &__drag-hint-icon {
540	    display: grid;
541	    place-items: center;
542	    filter: drop-shadow(0 10px 24px rgba(255, 255, 255, 0.08));
543	    transform-origin: 50% 8%;
544	    animation: works-drag-hint-icon-bell 2.6s ease-in-out infinite;
545	  }
546	
547	  &__drag-hint-text {
548	    @include font("f-body-3");
549	    font-family: var(--family-ui);
550	    letter-spacing: 0.14em;
551	    color: var(--clr-white-100);
552	    text-transform: uppercase;
553	    text-align: center;
554	  }
555	}
