540	      (entries) => {
541	        if (entries[0]?.isIntersecting) void this._loadMore();
542	      },
543	      { rootMargin: `${WORK_GRID_INFINITE_CONFIG.thresholdPx}px` },
544	    );
545	    this._sentinelObserver.observe(sentinel);
546	  }
547	
548	  private _detachSentinel(): void {
