802	  private _attachVideoHover(
803	    li: HTMLLIElement,
804	    videoUrl: string,
805	    figure: HTMLElement,
806	  ): void {
807	    const video = document.createElement("video");
808	    video.muted = true;
809	    video.loop = true;
810	    video.playsInline = true;
811	    video.preload = "none";
812	    figure.append(video);
813	
814	    let isHovered = false;
815	    let pendingPlay: Promise<void> | null = null;
816	
817	    const show = (): void => {
818	      if (isHovered) figure.classList.add("is-video-active");
819	    };
820	
821	    const hideVideoNow = (): void => {
822	      figure.classList.remove("is-video-active");
823	    };
824	
825	    const safePause = (): void => {
826	      video.pause();
827	      video.currentTime = 0;
828	    };
829	
830	    const drainAndPause = (): void => {
831	      const p = pendingPlay;
832	      pendingPlay = null;
833	      if (p !== null) {
834	        void p.then(() => { if (!isHovered) safePause(); });
835	      } else {
836	        safePause();
837	      }
838	    };
839	
840	    const onEnter = (): void => {
841	      isHovered = true;
842	      if (!video.src) {
843	        video.src = videoUrl;
844	        video.load();
845	      }
846	      pendingPlay = video.play().catch(() => undefined);
847	      if (video.readyState >= 3) {
848	        show();
849	      } else {
850	        video.addEventListener("canplay", show, { once: true });
851	      }
852	    };
853	
854	    const onLeave = (): void => {
855	      isHovered = false;
856	      video.removeEventListener("canplay", show);
857	      hideVideoNow();
858	      drainAndPause();
859	    };
860	
861	    li.addEventListener("pointerenter", onEnter);
862	    li.addEventListener("pointerleave", onLeave);
863	
864	    this._videoHoverCleanups.push(() => {
865	      isHovered = false;
866	      video.removeEventListener("canplay", show);
867	      figure.classList.remove("is-video-active");
868	      drainAndPause();
869	      li.removeEventListener("pointerenter", onEnter);
870	      li.removeEventListener("pointerleave", onLeave);
871	    });
872	  }
