1391	  private _bindScatterFilter(scene: WorksSceneManager): void {
1392	    this._unbindScatterFilter();
1393	    const wrap = this.elements.filterWrap;
1394	    const filterButton = this.elements.filterButton;
1395	    const filterPanel = this.elements.filterPanel;
1396	    if (!wrap || !filterButton || !filterPanel) return;
1397	
1398	    let closeAriaTimer: number | null = null;
1399	    const clearCloseAriaTimer = (): void => {
1400	      if (closeAriaTimer === null) return;
1401	      window.clearTimeout(closeAriaTimer);
1402	      closeAriaTimer = null;
1403	    };
1404	
1405	    const closePanel = (): void => {
1406	      clearCloseAriaTimer();
1407	      filterButton.setAttribute("aria-expanded", "false");
1408	      filterPanel.classList.remove("is-open");
1409	      // 패널 닫힘 트랜지션 후: 포커스 정리 + aria-hidden (WORKS_FILTER_TRANSITION_MS와 동기)
1410	      closeAriaTimer = window.setTimeout(() => {
1411	        closeAriaTimer = null;
1412	        const ae = document.activeElement;
1413	        if (ae instanceof Node && filterPanel.contains(ae)) {
1414	          filterButton.focus({ preventScroll: true });
1415	        }
1416	        filterPanel.setAttribute("aria-hidden", "true");
1417	      }, WORKS_FILTER_TRANSITION_MS);
1418	    };
1419	
1420	    const openPanel = (): void => {
1421	      clearCloseAriaTimer();
1422	      filterPanel.setAttribute("aria-hidden", "false");
1423	      filterPanel.classList.add("is-open");
1424	      filterButton.setAttribute("aria-expanded", "true");
1425	    };
1426	
1427	    const togglePanel = (): void => {
1428	      if (filterPanel.classList.contains("is-open")) {
1429	        closePanel();
1430	      } else {
1431	        openPanel();
1432	      }
1433	    };
1434	
1435	    const onFilterButtonClick = (event: MouseEvent): void => {
1436	      event.stopPropagation();
1437	      togglePanel();
1438	    };
1439	    filterButton.addEventListener("click", onFilterButtonClick);
1440	    this._scatterFilterCleanup.push(() =>
1441	      filterButton.removeEventListener("click", onFilterButtonClick),
1442	    );
1443	
1444	    const onPanelClick = (event: MouseEvent): void => {
1445	      const target = event.target as HTMLElement | null;
1446	      const option = target?.closest<HTMLElement>("[data-works-filter-option]");
1447	      if (!option) return;
1448	      const raw = option.dataset.category?.trim() ?? "";
1449	      const category = raw === "" ? null : raw;
1450	      this.state = { ...this.state, category };
1451	      this.elements.root?.setAttribute(
1452	        "data-category",
1453	        category === null ? "" : category,
1454	      );
1455	      scene.applyCategory(category);
1456	      this.uiRuntime?.syncFilterSelection(category, { animateLabel: true });
1457	      this.uiRuntime?.syncViewLinks(category);
1458	      this._syncScatterUrl(category);
1459	      closePanel();
1460	    };
1461	    filterPanel.addEventListener("click", onPanelClick);
1462	    this._scatterFilterCleanup.push(() =>
1463	      filterPanel.removeEventListener("click", onPanelClick),
1464	    );
1465	
1466	    const onDocumentClick = (event: MouseEvent): void => {
1467	      if (!wrap.contains(event.target as Node)) {
1468	        closePanel();
1469	      }
1470	    };
1471	    document.addEventListener("click", onDocumentClick);
1472	    this._scatterFilterCleanup.push(() =>
1473	      document.removeEventListener("click", onDocumentClick),
1474	    );
1475	
1476	    const onKeyDown = (event: KeyboardEvent): void => {
1477	      if (event.key !== "Escape") return;
1478	      closePanel();
1479	    };
1480	    document.addEventListener("keydown", onKeyDown);
1481	    this._scatterFilterCleanup.push(() =>
1482	      document.removeEventListener("keydown", onKeyDown),
1483	    );
1484	
1485	    this._scatterFilterCleanup.push(() => {
1486	      clearCloseAriaTimer();
1487	      if (!filterPanel.classList.contains("is-open")) {
1488	        filterPanel.setAttribute("aria-hidden", "true");
1489	      }
1490	    });
1491	  }
